174	pub(crate) fn load_marketplace_summary(
175	    path: &AbsolutePathBuf,
176	) -> Result<MarketplaceSummary, MarketplaceError> {
177	    let marketplace = load_marketplace(path)?;
178	    let mut plugins = Vec::new();
179	
180	    for plugin in marketplace.plugins {
181	        let MarketplacePlugin {
182	            name,
183	            source,
184	            install_policy,
185	            auth_policy,
186	            category,
187	        } = plugin;
188	        let source_path = resolve_plugin_source_path(path, source)?;
189	        let source = MarketplacePluginSourceSummary::Local {
190	            path: source_path.clone(),
191	        };
192	        let mut interface = load_plugin_manifest(source_path.as_path())
193	            .and_then(|manifest| plugin_manifest_interface(&manifest, source_path.as_path()));
194	        if let Some(category) = category {
195	            // Marketplace taxonomy wins when both sources provide a category.
196	            interface
197	                .get_or_insert_with(PluginManifestInterfaceSummary::default)
198	                .category = Some(category);
199	        }
200	
201	        plugins.push(MarketplacePluginSummary {
202	            name,
203	            source,
204	            install_policy,
205	            auth_policy,
206	            interface,
207	        });
208	    }
209	
210	    Ok(MarketplaceSummary {
211	        name: marketplace.name,
212	        path: path.clone(),
213	        plugins,
214	    })
215	}
